import{_ as s,C as a,o as n,c as l,j as d,a as i,G as e,a7 as c}from"./chunks/framework.BvFspj3b.js";const _=JSON.parse('{"title":"安装与更新通道","description":"ICC-CE 的系统要求、安装版与绿色版的区别、四个更新通道的含义","frontmatter":{"title":"安装与更新通道","description":"ICC-CE 的系统要求、安装版与绿色版的区别、四个更新通道的含义"},"headers":[],"relativePath":"cn/guide/installation.md","filePath":"cn/guide/installation.md"}'),h={name:"cn/guide/installation.md"};function g(p,t,u,b,C,k){const o=a("ArticleMetadata"),r=a("KnownBugs");return n(),l("div",null,[t[0]||(t[0]=d("h1",{id:"安装与更新通道",tabindex:"-1"},[i("安装与更新通道 "),d("a",{class:"header-anchor",href:"#安装与更新通道","aria-label":'Permalink to "安装与更新通道"'},"​")],-1)),e(o),e(r),t[1]||(t[1]=c('<h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><p>在开始之前，请确认你的设备满足以下条件：</p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td><strong>操作系统</strong></td><td>Windows 10 版本 1809（build 17763）及以上，或 Windows 11</td></tr><tr><td><strong>运行时</strong></td><td>.NET 6 桌面运行时（x64 或 x86）</td></tr><tr><td><strong>内存</strong></td><td>建议 4 GB 以上</td></tr><tr><td><strong>显卡</strong></td><td>支持 Direct3D 11 的显卡可启用硬件加速墨迹渲染</td></tr><tr><td><strong>输入设备</strong></td><td>鼠标可用；触摸屏 / 数位板 / 主动式电容笔体验更佳</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">如何查看系统版本？</p><p>按 <kbd>Win</kbd> + <kbd>Pause</kbd> 即可打开系统信息，查看 Windows 版本和系统类型（64 位 / 32 位）。</p></div><div class="warning custom-block"><p class="custom-block-title">关于 .NET 运行时</p><p>ICC-CE 运行在 .NET 6 上，<strong>不是</strong> .NET Framework。安装版会在需要时自动提示下载运行时；绿色版若无法启动，多半是缺少 .NET 6 桌面运行时，请到微软官网搜索 &quot;.NET Desktop Runtime 6.x&quot; 下载安装对应架构（x64 / x86）的版本。</p></div><h2 id="获取安装包" tabindex="-1">获取安装包 <a class="header-anchor" href="#获取安装包" aria-label="Permalink to &quot;获取安装包&quot;">​</a></h2><p>访问 <a href="/website/cn/download">下载中心</a> 选择你需要的版本。页面会自动检测最优下载线路。</p><h3 id="四个更新通道的区别" tabindex="-1">四个更新通道的区别 <a class="header-anchor" href="#四个更新通道的区别" aria-label="Permalink to &quot;四个更新通道的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>通道</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Beta（推荐）</strong></td><td>更新最快、修复最及时，经过 CI 自动构建和基本验证</td><td>日常使用首选</td></tr><tr><td><strong>Preview</strong></td><td>不含 pre-release 标记的版本，比 Beta 更收敛</td><td>想尝鲜又偏好稳定</td></tr><tr><td><strong>正式版（Release）</strong></td><td>发布频率最低，经过完整测试</td><td>对稳定性要求极高的正式环境</td></tr><tr><td><strong>Nightly</strong></td><td>未经测试的 Debug 产物，直接由 net6 分支最新代码构建</td><td><strong>仅用于测试，绝对不可用于正式课堂</strong></td></tr></tbody></table><blockquote><p>Nightly 构建在下载前需要阅读风险说明并勾选确认，且更新到下一个 Nightly 版本需要手动下载替换，不会自动更新。</p></blockquote><h2 id="安装版-vs-绿色版" tabindex="-1">安装版 vs 绿色版 <a class="header-anchor" href="#安装版-vs-绿色版" aria-label="Permalink to &quot;安装版 vs 绿色版&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>安装版（.exe）</th><th>绿色版（.zip）</th></tr></thead><tbody><tr><td>安装方式</td><td>运行安装向导，自动完成</td><td>解压到任意目录即可</td></tr><tr><td>快捷方式</td><td>自动创建开始菜单和桌面快捷方式</td><td>需手动创建</td></tr><tr><td>写入系统</td><td>安装目录、注册表卸载项</td><td>完全不写系统</td></tr><tr><td>卸载</td><td>设置 → 应用 → 已安装的应用 → 卸载</td><td>直接删除文件夹</td></tr><tr><td>适用场景</td><td>个人电脑、班级一体机长期使用</td><td>U 盘便携、机房批量部署、多版本并存</td></tr></tbody></table><h2 id="_32-位还是-64-位" tabindex="-1">32 位还是 64 位？ <a class="header-anchor" href="#_32-位还是-64-位" aria-label="Permalink to &quot;32 位还是 64 位？&quot;">​</a></h2><ul><li>现代设备一律选 <strong>64 位（x64）</strong></li><li>仅在系统为 32 位、或需要与 32 位 Office 深度联动时选 <strong>32 位（x86）</strong></li></ul><h2 id="安装后的目录结构" tabindex="-1">安装后的目录结构 <a class="header-anchor" href="#安装后的目录结构" aria-label="Permalink to &quot;安装后的目录结构&quot;">​</a></h2><p>安装完成后，主程序和数据目录默认位于：</p><ul><li><strong>安装版</strong>：<code>C:\\Program Files\\InkCanvasForClass CE\\</code>（或自定义安装目录）</li><li><strong>绿色版</strong>：你解压到的目录</li></ul><p>用户配置和墨迹数据保存在：</p><ul><li><strong>配置文件</strong>：<code>%AppData%\\InkCanvasForClass CE\\Configs\\Settings.json</code></li><li><strong>自动保存墨迹</strong>：<code>%AppData%\\InkCanvasForClass CE\\Saves\\</code></li><li><strong>截图</strong>：<code>%USERPROFILE%\\Pictures\\Ink Canvas Screenshots\\</code></li><li><strong>日志文件</strong>：<code>%AppData%\\InkCanvasForClass CE\\Logs\\</code></li></ul><h2 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h2><p>ICC-CE 内置在线更新检查。手动升级时：</p><ul><li><strong>安装版</strong>：直接运行新版本安装包覆盖安装即可，配置与墨迹保留</li><li><strong>绿色版</strong>：解压新版本到旧版本程序目录覆盖即可</li></ul><div class="warning custom-block"><p class="custom-block-title">跨通道切换</p><p>从 Beta 回退到正式版时，可能出现新版本写入的配置项无法被旧版本识别的情况。如遇异常，请备份后删除配置文件让程序重新生成。</p></div>',23))])}const x=s(h,[["render",g]]);export{_ as __pageData,x as default};
